sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
/* ─── Reset ───────────────────────────────────────────── */
.gnf-footer *,
.gnf-footer *::before,
.gnf-footer *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* ─── Footer wrapper ──────────────────────────────────── */
.gnf-footer {
  font-family: 'Inter', 'Plus Jakarta Sans', 'Segoe UI', sans-serif;
  background: #1c1c1e;
  width: calc(100% + 30px);
  margin-left: -15px;
  margin-right: -15px;
}

/* ─── Inner container ─────────────────────────────────── */
.gnf-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 60px;
}

/* ─── TOP ROW: brand + nav ────────────────────────────── */
.gnf-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 60px;
  padding: 52px 0 44px;
}

/* ─── Brand block ─────────────────────────────────────── */
.gnf-brand {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 0 0 auto;
  max-width: 260px;
}

.gnf-logo {
  display: flex;
  align-items: center;
  gap: 9px;
}

.gnf-logo-icon {
  color: #ffffff;
  flex-shrink: 0;
}

.gnf-logo-name {
  font-size: 17px;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.gnf-tagline {
  font-size: 13px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.45);
  line-height: 1.65;
}

/* ─── Nav columns ─────────────────────────────────────── */
.gnf-nav {
  display: flex;
  gap: 64px;
  flex-shrink: 0;
}

.gnf-col {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-width: 120px;
}

.gnf-col-heading {
  font-size: 13px;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: 0.01em;
}

.gnf-col-list {
  display: flex;
  flex-direction: column;
  gap: 11px;
}

.gnf-link {
  font-size: 13px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.50);
  text-decoration: none !important;
  transition: color 0.18s ease;
  white-space: nowrap;
}

.gnf-link:hover {
  color: rgba(255, 255, 255, 0.85);
}

/* ─── BOTTOM BAR ──────────────────────────────────────── */
.gnf-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 0 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.10);
}

.gnf-copyright {
  font-size: 12px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.35);
}

.gnf-legal {
  display: flex;
  align-items: center;
  gap: 24px;
}

.gnf-legal-link {
  font-size: 12px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.35);
  text-decoration: none !important;
  transition: color 0.18s ease;
}

.gnf-legal-link:hover {
  color: rgba(255, 255, 255, 0.70);
}

/* ─── Responsive ──────────────────────────────────────── */
@media (max-width: 1024px) {
  .gnf-inner { padding: 0 40px; }
  .gnf-nav   { gap: 40px; }
}

@media (max-width: 768px) {
  .gnf-top {
    flex-direction: column;
    gap: 40px;
    padding: 40px 0 36px;
  }
  .gnf-inner  { padding: 0 32px; }
  .gnf-brand  { max-width: 100%; }
  .gnf-nav    { gap: 32px; flex-wrap: wrap; }
}

@media (max-width: 520px) {
  .gnf-inner  { padding: 0 20px; }
  .gnf-nav    { gap: 28px; }
  .gnf-bottom {
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
  }
}
